import React, { useState, useEffect } from 'react';
import bcrypt from 'bcryptjs';
import CryptoJS from "crypto-js";
import users from '../data/users.json'; // Import the encrypted user data
import VideoProvider from "../context/VideoContext";
import ScrollingCards from "../components/ScrollingCards";
import videos from '../data/videoLinks.json'; // Import the videos data
import '../App.css'

const secretKey = "your-secret-key"; // Keep this secret!

const PasswordProtection = ({ onPasswordSuccess }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showNewUserMessage, setShowNewUserMessage] = useState(true);

  useEffect(() => {
    document.getElementById("email").focus();
  }, []);

  const isEmailValid = email.includes('@gmail.com');
  const isPasswordValid = password.length >= 10;

  // Function to handle key press
  const handleKeyDown = (event) => {
    if (event.key === "Enter" && isEmailValid && isPasswordValid) {
      handleSubmit();
    }
  };

  // Function to decrypt a password (Only for sharing purposes)
  const decryptPassword = (encryptedPassword) => {
    const bytes = CryptoJS.AES.decrypt(encryptedPassword, secretKey);
    return bytes.toString(CryptoJS.enc.Utf8);
  };

  // Function to handle user login
  const handleSubmit = async () => {
    setLoading(true); // Show preloader
    setShowNewUserMessage(false); // Hide new users message

    setTimeout(async () => {
      const user = users.find(u => u.email.concat("@gmail.com") === email);

      if (user) {
        const isMatch = await bcrypt.compare(password, user.password);
        if (isMatch) {
          onPasswordSuccess();
        } else {
          setError(true);
        }
      } else {
        setError(true);
      }
      setLoading(false); // Hide the preloader after 5 seconds
    }, 5000); // Delay of 5 seconds
  };

  return (
    <div>
      {loading && (
        <div className="preloader-container">
          <div className="loader"></div>
        </div>
      )}

      {/* Scrolling Cards */}
      <div className="scrolling-cards-container">
        <VideoProvider>
          <ScrollingCards />
        </VideoProvider>
      </div>

      <div className="container" style={{ textAlign: 'center', padding: '20px' }}>
        <h1>Welcome to PTE Write From Dictation</h1>
        <h2>Please enter your email and password to continue</h2>

        {/* New Users Message */}
        {showNewUserMessage && (
          <div style={{ marginBottom: '15px', color: '#333' }}>
            <strong>New Users: </strong>
            <a
              href="https://www.example.com/tutorial-video"
              target="_blank"
              rel="noopener noreferrer"
              style={{ textDecoration: 'none', color: 'blue', fontWeight: 'bold' }}
            >
              Click here
            </a>
            &nbsp;and follow the steps to get access to the website.
          </div>
        )}

        {/* Email input field */}
        <input
          id="email"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          onKeyDown={handleKeyDown} // Listen for Enter key
          placeholder="Enter your email address"
          style={{ padding: '10px', margin: '10px', width: '300px' }}
          disabled={loading} // Disable input when loading
        />

        {/* Password input field */}
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={handleKeyDown} // Listen for Enter key
          placeholder="Enter password"
          style={{ padding: '10px', margin: '10px', width: '300px' }}
          disabled={loading} // Disable input when loading
        />

        {/* Submit button */}
        <button
          onClick={handleSubmit}
          style={{
            padding: '10px',
            backgroundColor: (isEmailValid && isPasswordValid) ? '#4CAF50' : '#A5D6A7',
            color: 'white',
            cursor: (isEmailValid && isPasswordValid) ? 'pointer' : 'not-allowed',
            border: 'none',
            borderRadius: '5px'
          }}
          disabled={!isEmailValid || !isPasswordValid || loading} // Disable button if loading
        >
          Submit
        </button>

        {/* Loading Indicator */}
        {loading && (
          <div style={{ marginTop: '20px' }}>
            <div className="spinner"></div>
            <p>Processing... Please wait.</p>
          </div>
        )}

        {/* Error Message */}
        {error && !loading && (
          <div>
            <p style={{ color: 'red' }}>Incorrect email or password. Please try again.</p>
            <p>Too many incorrect attempts will result in your account being locked.</p>
            <p>
              If you've forgotten your password, please
              <a
                href="https://www.youtube.com/channel/UCMJeoG6jGrGtk3noLZ6bJMg?sub_confirmation=1"
                target="_blank"
                rel="noopener noreferrer"
                style={{ textDecoration: 'none', color: 'blue', fontWeight: 'bold', marginLeft: '5px' }}
              >
                contact the admin over here
              </a>.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PasswordProtection;
